script.setup:
// glTF Transform reads the GLB (made by trimesh through recipe trimesh.displaced-sphere-glb):
// positions, normals, vertex colors and indices go straight into WebGL buffers.
const { WebIO } = await ctx.utils.import("https://esm.sh/@gltf-transform/core@4.5.0");
const doc = await new WebIO().readBinary(new Uint8Array(await (await fetch(ctx.assets["sculpture.glb"])).arrayBuffer()));
const prim = doc.getRoot().listMeshes()[0].listPrimitives()[0];
const gl = ctx.gl, vao = gl.createVertexArray();
gl.bindVertexArray(vao);
const attribute = (name, location) => {
  const acc = prim.getAttribute(name);
  if (!acc) return;
  const array = acc.getArray();
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, array, gl.STATIC_DRAW);
  const type = array instanceof Uint8Array ? gl.UNSIGNED_BYTE : array instanceof Uint16Array ? gl.UNSIGNED_SHORT : gl.FLOAT;
  gl.enableVertexAttribArray(location);
  gl.vertexAttribPointer(location, acc.getElementSize(), type, acc.getNormalized() || type !== gl.FLOAT, 0, 0);
};
const indices = prim.getIndices().getArray();
attribute("POSITION", 0); attribute("COLOR_0", 3);
if (prim.getAttribute("NORMAL")) attribute("NORMAL", 1);
else {
  // Some GLBs carry no normals: average the face normals at each vertex.
  const pos = prim.getAttribute("POSITION").getArray(), normals = new Float32Array(pos.length);
  for (let i = 0; i < indices.length; i += 3) {
    const [a, b, c] = [indices[i] * 3, indices[i + 1] * 3, indices[i + 2] * 3];
    const e1 = [pos[b] - pos[a], pos[b + 1] - pos[a + 1], pos[b + 2] - pos[a + 2]], e2 = [pos[c] - pos[a], pos[c + 1] - pos[a + 1], pos[c + 2] - pos[a + 2]];
    const n = [e1[1] * e2[2] - e1[2] * e2[1], e1[2] * e2[0] - e1[0] * e2[2], e1[0] * e2[1] - e1[1] * e2[0]];
    for (const v of [a, b, c]) { normals[v] += n[0]; normals[v + 1] += n[1]; normals[v + 2] += n[2]; }
  }
  gl.bindBuffer(gl.ARRAY_BUFFER, gl.createBuffer());
  gl.bufferData(gl.ARRAY_BUFFER, normals, gl.STATIC_DRAW);
  gl.enableVertexAttribArray(1);
  gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 0, 0);
}
gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, gl.createBuffer());
gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, indices, gl.STATIC_DRAW);
gl.bindVertexArray(null);
Object.assign(ctx.state, { vao, count: indices.length, indexType: indices instanceof Uint32Array ? gl.UNSIGNED_INT : gl.UNSIGNED_SHORT,
  camera: ctx.utils.createOrbitCamera({ distance: 3.6, theta: 0.6, phi: 1.2 }),
  p: ctx.utils.createProgram("#version 300 es\nlayout(location=0) in vec3 a_position; layout(location=1) in vec3 a_normal; layout(location=3) in vec4 a_color;\nuniform mat4 u_mvp, u_model; out vec3 v_n; out vec3 v_c;\nvoid main(){ v_n = mat3(u_model) * a_normal; v_c = a_color.rgb; gl_Position = u_mvp * vec4(a_position, 1.0); }", "#version 300 es\nprecision highp float; in vec3 v_n; in vec3 v_c; out vec4 outColor; uniform float u_rim;\nvoid main(){ vec3 n = normalize(v_n); float d = max(dot(n, normalize(vec3(0.5, 0.8, 0.6))), 0.0);\n  float rim = pow(1.0 - abs(n.z), 3.0) * u_rim;\n  outColor = vec4(v_c * (0.18 + 0.82 * d) + rim * vec3(0.6, 0.7, 1.0), 1.0); }") });
ctx.publish("triangles", indices.length / 3);

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, { mat4 } = ctx.utils, [w, h] = ctx.resolution;
s.camera.update(ctx.mouse, ctx.mousePrev, ctx.mouseDown, ctx.keys, ctx.dt);
const model = mat4.fromYRotation(ctx.time * u.u_spin);
const mvp = mat4.multiply(s.camera.getProjectionMatrix(w / h, 40, 0.1, 50), mat4.multiply(s.camera.getViewMatrix(), model));
gl.enable(gl.DEPTH_TEST);
gl.clearColor(0.04, 0.04, 0.06, 1); gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT);
gl.useProgram(s.p);
ctx.utils.setUniforms(s.p, { u_mvp: mvp, u_model: model, u_rim: u.u_rim });
gl.bindVertexArray(s.vao);
gl.drawElements(gl.TRIANGLES, s.count, s.indexType, 0);
gl.bindVertexArray(null);
